class RandomizedCollection {
    private java.util.ArrayList<Integer> list;
    private java.util.HashMap<Integer, java.util.LinkedHashSet<Integer>> map;
    private java.util.Random rand;

    public RandomizedCollection() {
        list = new java.util.ArrayList<>();
        map = new java.util.HashMap<>();
        rand = new java.util.Random();
    }

    public boolean insert(int val) {
        boolean notPresent = !map.containsKey(val) || map.get(val).isEmpty();
        map.computeIfAbsent(val, k -> new java.util.LinkedHashSet<>()).add(list.size());
        list.add(val);
        return notPresent;
    }

    public boolean remove(int val) {
        if (!map.containsKey(val) || map.get(val).isEmpty()) return false;
        int removeIdx = map.get(val).iterator().next();
        map.get(val).remove(removeIdx);
        int lastIdx = list.size() - 1;
        int lastVal = list.get(lastIdx);
        if (removeIdx != lastIdx) {
            list.set(removeIdx, lastVal);
            map.get(lastVal).remove(lastIdx);
            map.get(lastVal).add(removeIdx);
        }
        list.remove(lastIdx);
        return true;
    }

    public int getRandom() {
        return list.get(rand.nextInt(list.size()));
    }
}

import java.util.*;

class RandomizedCollection {
    private List<Integer> list;
    private Map<Integer, Set<Integer>> idxMap;
    private Random rand;

    public RandomizedCollection() {
        list = new ArrayList();
        idxMap = new HashMap();
        rand = new Random();
    }

    public boolean insert(int val) {
        boolean isNew = !idxMap.containsKey(val) || idxMap.get(val).isEmpty();
        if (!idxMap.containsKey(val)) {
            idxMap.put(val, new HashSet());
        }
        idxMap.get(val).add(list.size());
        list.add(val);
        return isNew;
    }

    public boolean remove(int val) {
        if (!idxMap.containsKey(val) || idxMap.get(val).isEmpty()) return false;
        Set<Integer> indices = idxMap.get(val);
        int removeIdx = indices.iterator().next();
        indices.remove(removeIdx);
        int lastIdx = list.size() - 1;
        int lastVal = list.get(lastIdx).intValue();
        if (removeIdx != lastIdx) {
            list.set(removeIdx, lastVal);
            Set<Integer> lastIndices = idxMap.get(lastVal);
            lastIndices.remove(lastIdx);
            lastIndices.add(removeIdx);
        }
        list.remove(lastIdx);
        return true;
    }

    public int getRandom() {
        return list.get(rand.nextInt(list.size())).intValue();
    }
}
